/// Find all minimal windows of consecutive lines (spanning at most `line_count`
/// lines) where every query appears at least once across the window. Larger
/// windows that strictly contain a smaller valid window are omitted, so only the
/// tightest-fitting windows are reported.
fn search_within_lines(
    root: &Path,
    path: &Path,
    lines: &[&str],
    matcher: &SearchMatcher,
    line_count: usize,
    context_lines: usize,
    matches: &mut Vec<MemorySearchMatch>,
) {
    let query_count = matcher.queries.len();
    let per_line = lines
        .iter()
        .map(|line| matcher.matched_query_indices(line))
        .collect::<Vec<_>>();

    // For each start line `s`, compute the smallest end line `e` such that the
    // window [s, e] covers every query (or None when no such window exists).
    // `right` is monotonic across iterations, keeping this linear.
    let line_len = lines.len();
    let mut smallest_end = vec![None; line_len];
    let mut counts = vec![0usize; query_count];
    let mut covered = 0usize;
    let mut right = 0usize;
    for start in 0..line_len {
        while covered < query_count && right < line_len {
            for &query_index in &per_line[right] {
                if counts[query_index] == 0 {
                    covered += 1;
                }
                counts[query_index] += 1;
            }
            right += 1;
        }
        if covered == query_count {
            smallest_end[start] = Some(right - 1);
        }
        for &query_index in &per_line[start] {
            counts[query_index] -= 1;
            if counts[query_index] == 0 {
                covered -= 1;
            }
        }
    }

    for start in 0..line_len {
        let Some(end) = smallest_end[start] else {
            continue;
        };
        // Reject windows that span more than the requested number of lines.
        if end - start + 1 > line_count {
            continue;
        }
        // Drop windows that strictly contain a narrower valid window: if the
        // window starting one line later still covers every query without
        // extending past `end`, then this line is redundant.
        let contains_narrower = match smallest_end.get(start + 1).copied().flatten() {
            Some(next_end) => next_end <= end,
            None => false,
        };
        if contains_narrower {
            continue;
        }

        matches.push(build_match(
            root,
            path,
            lines,
            start,
            end,
            matcher.queries.clone(),
            context_lines,
        ));
    }
}

